//! The UniFFI scaffolding.
//!
//! The UDL in `src/stride.udl` is the description of the surface; this
//! generates the Rust side of it. The Kotlin side is generated by
//! `uniffi-bindgen`, which the Gradle build runs.

use std::fs;
use std::path::PathBuf;

fn main() {
    // The build script may panic: a build script that fails is a build
    // failure, and there is nobody to show an error to.
    #[allow(clippy::expect_used, clippy::panic)]
    {
        uniffi::generate_scaffolding("src/stride.udl")
            .expect("the UniFFI scaffolding could not be generated");
    }

    allow_the_generated_ffi();
}

/// Let the generated scaffolding use `unsafe`.
///
/// The scaffolding is the FFI boundary: every one of its functions is a
/// `#[no_mangle]` symbol the Kotlin bindings call. The crate denies
/// `unsafe_code`, and the lint cannot tell that this file is *generated* —
/// so the allowance is put here, on the generated items, and the lint stays
/// armed for the rest of the crate.
fn allow_the_generated_ffi() {
    let out_dir = match std::env::var_os("OUT_DIR") {
        Some(dir) => PathBuf::from(dir),
        None => return,
    };
    let generated = out_dir.join("stride.uniffi.rs");
    let Ok(text) = fs::read_to_string(&generated) else {
        return;
    };
    if text.contains("#[allow(unsafe_code)]") {
        return;
    }
    let patched = text.replace(
        "#[unsafe(no_mangle)]",
        "#[allow(unsafe_code)]\n#[unsafe(no_mangle)]",
    );
    let _ = fs::write(&generated, patched);
}
